def get_letter_choices():
    letter_choices = []
    for c in 'abcdefghijklmnopqrstuvwxyz':
        letter_choices.append(c)

    return letter_choices

def letter_to_num(c):
    return ord(c) - 97

def num_to_letter(n):
    return chr(n + 97)

def generate_letter_pairs(letter_choices):
    letter_pairs = []
    for i in range(len(letter_choices) - 1):
        first_letter = letter_choices[i]
        second_letter = letter_choices[i + 1]

        pair = (first_letter, second_letter)
        letter_pairs.append(pair)

    return letter_pairs

def plot_plan(letter_choices):
    pairs = generate_letter_pairs(letter_choices)
